import {decorateAcademicPage} from './academic-page-layout.mjs';
import {writeContentManifest} from './content-manifest.mjs';
import {writeDecisionGuides} from './decision-guides.mjs';
import {writeAcademicGuides} from './academic-guides.mjs';
import fs from 'node:fs';
import path from 'node:path';
import {iconifyHTML} from '../src/icons.mjs';
import {getCourseSpecs} from '../src/course-specs.mjs';
import {courses,areas,articles,events,services,faqs,portalNav} from '../src/data.mjs';
const school=JSON.parse(fs.readFileSync('school.config.json','utf8'));
if(typeof school.id!=='string'||typeof school.shortName!=='string'||typeof school.country!=='string'||!/^[a-z0-9-]{2,48}$/.test(school.id)||!/[\p{L}\p{N}]/u.test(school.shortName)||!/^[\p{L}\p{N} .-]{2,40}$/u.test(school.shortName)||!/^[\p{L} .-]{2,50}$/u.test(school.country))throw Error('Configuração da escola inválida.');
function brand(text){return text.replaceAll('ISPAB',()=>school.shortName).replaceAll('Angola',()=>school.country)}
let portal=null;
if(school.portalUrl){portal=new URL(school.portalUrl);if(portal.protocol!=='https:'||portal.username||portal.password||portal.hash||[...portal.searchParams.keys()].some(k=>k!=='escola'))throw Error('URL do portal SIGA inválido.');}
const out='dist';fs.mkdirSync(out,{recursive:true});fs.cpSync('public',out,{recursive:true});fs.mkdirSync(out+'/integration',{recursive:true});fs.copyFileSync('integration/client.mjs',out+'/integration/client.mjs');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo=`<svg viewBox="0 0 36 36" aria-hidden="true"><path d="M5 12 18 5l13 7-13 7zM5 19l13 7 13-7M5 26l13 7 13-7"/></svg><span>ISPAB<span class="brand-dot">.</span></span>`;
const link=(url,label,style='button')=>`<a class="${style}" href="${url}">${label}<span aria-hidden="true">↗</span></a>`;
const notice=(text='Conteúdo demonstrativo. A oferta, os requisitos e os prazos dependem de validação institucional.')=>`<div class="notice"><span aria-hidden="true">ⓘ</span><p>${text}</p></div>`;
const crumb=(title,extra='')=>`<div class="breadcrumb wrap"><a href="/">Início</a><span>/</span>${extra}<span>${esc(title)}</span></div>`;
function menu(title,links,feature){return `<details class="nav-dropdown"><summary>${title}<span>⌄</span></summary><div class="mega-menu"><div class="menu-highlight"><span class="eyebrow">O SEU PRÓXIMO PASSO</span><h3>${feature[0]}</h3><p>${feature[1]}</p>${link(feature[2],feature[3],'text-link')}</div><div class="mega-links">${links.map(([url,label,sub])=>`<a href="${url}"><strong>${label} <span>↗</span></strong><small>${sub}</small></a>`).join('')}</div></div></details>`}
function header(url){return `<a class="skip-link" href="#main">Saltar para o conteúdo</a><div class="site-navigation"><div class="topline"><div class="wrap"><span>ISPAB · Angola <i></i> Prévia institucional</span><div><a href="/candidaturas/">Área do candidato</a><a href="/ajuda/">Ajuda</a><a href="/contactos/">Contactos ↗</a></div></div></div><header class="site-header" data-navigation-context="${url==='/'?'home':'inner'}"><div class="header-inner wrap"><a class="brand" href="/" aria-label="ISPAB, início">${logo}</a><button class="mobile-toggle icon-button" aria-expanded="false" aria-controls="main-nav" aria-label="Abrir navegação">☰</button><nav id="main-nav" aria-label="Navegação principal">${menu('Estudar',[['/cursos/','Todos os cursos','Encontre a sua área de formação'],['/cursos/?nivel=Licenciatura','Licenciaturas','Comece a sua jornada académica'],['/cursos/?nivel=Pós-graduação','Pós-graduação','Aprofunde os seus conhecimentos'],['/cursos/?nivel=Curso%20de%20curta%20dura%C3%A7%C3%A3o','Cursos de curta duração','Novas competências, novos caminhos'],['/escolher-curso/','Como escolher um curso','Interesses, rotina e próximos passos'],['/comparar/','Comparar cursos','Escolha com mais confiança'],['/favoritos/','Os meus favoritos','Volte às suas descobertas']],[ 'Um futuro com a sua assinatura.','Explore conhecimentos que combinam com os seus interesses.','/cursos/','Descobrir cursos'])}${menu('Ingresso',[['/ingresso/','Como candidatar-se','Conheça cada etapa do percurso'],['/candidatura/','Iniciar candidatura','Experimente a inscrição online'],['/candidaturas/','Acompanhar candidatura','Consulte os seus registos locais'],['/preparar-candidatura/','Preparar a candidatura','Uma lista pessoal para se organizar'],['/percursos-de-ingresso/','Outros percursos','Transferências e estudos no estrangeiro'],['/bolsas/','Bolsas e apoios','Oriente o seu planeamento'],['/calendario/','Calendário','Organize os próximos passos']],[ 'O primeiro passo é seu.','Da escolha do curso à preparação da sua candidatura.','/ingresso/','Ver formas de ingresso'])}${menu('Vida académica',[['/vida-academica/','Viver o campus','Aprender também é pertencer'],['/novos-estudantes/','Novos estudantes','Prepare a chegada e a primeira semana'],['/campus/','Espaços e campus','Explore a visão do ambiente académico'],['/investigacao/','Investigação e extensão','Ideias em contacto com a sociedade'],['/blog/','Blog da escola','Leituras para a sua jornada'],['/eventos/','Agenda de eventos','Encontros que abrem perspectivas']],[ 'Conhecimento em movimento.','Descubra uma experiência que vai além da sala de aula.','/vida-academica/','Explorar a vida académica'])}${menu('Serviços',[['/servicos/','Todos os serviços','Encontre o apoio de que precisa'],['/biblioteca/','Biblioteca','Fontes abertas e recursos de estudo'],['/apoio-ao-estudante/','Apoio ao estudante','Acolhimento e orientação'],['/carreiras/','Carreiras e estágios','Prepare o próximo passo'],['/servicos/secretaria/','Secretaria académica','Informações e requerimentos'],['/ajuda/','Central de ajuda','Respostas às suas perguntas']],[ 'Mais simples. Mais próximo.','Serviços organizados à volta da sua experiência académica.','/servicos/','Encontrar um serviço'])}<a class="simple-nav" href="/sobre/">O ISPAB</a><div class="mobile-actions"><a href="/login/">Entrar no portal ↗</a></div></nav><div class="header-actions"><a class="header-search" href="/pesquisa/" aria-label="Pesquisar no site"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg></a><a class="button small" href="/login/">Portal académico <span>↗</span></a></div></div></header></div>`}
function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-main"><div><a class="brand" href="/">${logo}</a><p>Conhecimento que aproxima.<br>Possibilidades que transformam.</p><span class="locale">◎ Angola · Ensino superior</span></div><div><h3>Encontre o seu caminho</h3><a href="/cursos/">Cursos</a><a href="/ingresso/">Formas de ingresso</a><a href="/bolsas/">Bolsas e apoios</a><a href="/candidatura/">Candidatura</a><a href="/preparar-candidatura/">Preparar a candidatura</a></div><div><h3>Viva o ISPAB</h3><a href="/sobre/">A instituição</a><a href="/vida-academica/">Vida académica</a><a href="/novos-estudantes/">Novos estudantes</a><a href="/investigacao/">Investigação e extensão</a><a href="/noticias/">Notícias e histórias</a><a href="/eventos/">Eventos</a></div><div><h3>Estamos por perto</h3><a href="/servicos/">Serviços académicos</a><a href="/login/">Portal académico</a><a href="/biblioteca/">Biblioteca</a><a href="/ajuda/">Central de ajuda</a><a href="/contactos/">Contactos</a></div></div><div class="footer-demo">Versão demonstrativa do ISPAB. Cursos, imagens, eventos e dados académicos ilustrativos. As candidaturas e os pedidos desta prévia não são enviados à instituição.</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ISPAB · Prévia de website</span><div><a href="/privacidade/">Privacidade</a><a href="/acessibilidade/">Acessibilidade</a><a href="/mapa-do-site/">Mapa do site</a><a href="/sobre-o-projecto/">Sobre o projecto</a></div><a href="#top">Voltar ao topo ↑</a></div></div></footer>`}
const routes=[];const searchContent=new Map();
function write(url,title,body,{portal=false,description,active=''}={}){body=decorateAcademicPage(url,body);const html=`<!doctype html><html lang="pt-AO"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#1558ee"><meta name="description" content="${esc(description||title+' — Explore a experiência académica do ISPAB, Angola. Website demonstrativo.')}"><title>${esc(title)} | ISPAB</title><link rel="icon" href="/assets/icon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Manrope:wght@400;500;600;650;700;750;800&display=swap" rel="stylesheet"><link href="/style.css" rel="stylesheet"></head><body id="top" data-page="${esc(active||url)}" class="${portal?'portal-body':''}">${portal?'':header(url)}${portal?body:`<main id="main">${body}</main>${footer()}`}<div id="toast" role="status" aria-live="polite"></div><dialog id="site-dialog"><button class="dialog-close icon-button" aria-label="Fechar janela">×</button><div id="dialog-content"></div></dialog><script type="module" src="/app.js"></script></body></html>`;const dir=path.join(out,url);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),iconifyHTML(brand(portal?html.replace('href="/signin-with-chatgpt?return_to=%2Fportal%2F"',()=>`href="${esc(portal.href)}"`).replace('Entrar com ChatGPT','Entrar no SIGA Plus'):html)));routes.push({url,title});searchContent.set(url,body.replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim().slice(0,12000))}
function pageHead(label,title,desc,extra=''){return `<section class="page-head"><div class="wrap"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p>${extra}</div><span class="head-spark" aria-hidden="true">✳</span></section>`}
function courseCard(c){const area=areas.find(a=>a.id===c.area);return `<article class="course-card" data-course="${c.id}"><div class="course-img ${area.color}"><a href="/cursos/${c.id}/" tabindex="-1" aria-hidden="true"><img src="/assets/${c.image}.webp" alt="" loading="lazy"></a><span class="pill">${c.level}</span><button class="favorite-button" data-favorite="${c.id}" aria-label="Guardar ${c.name} nos favoritos" aria-pressed="false">♡</button></div><div class="course-content"><span class="eyebrow course-area-label"><i class="area-dot ${area.color}"></i>${area.name}</span><h3><a href="/cursos/${c.id}/">${c.name}</a></h3><p>${c.description}</p><div class="course-meta"><span>◷ ${c.duration}</span><span>◎ ${c.mode}</span><span>☷ ${c.shift}</span></div><div class="course-actions"><a href="/cursos/${c.id}/">Conhecer o curso <span>↗</span></a><label><input type="checkbox" data-compare="${c.id}"> Comparar</label></div></div></article>`}
const searchBox=(id='hero-search')=>`<form class="course-search" action="/cursos/" id="${id}"><div><span aria-hidden="true">⌕</span><label class="sr-only" for="${id}-q">Nome ou área do curso</label><input id="${id}-q" name="q" placeholder="O que quer aprender?" type="search"></div><label class="sr-only" for="${id}-level">Nível de formação</label><select id="${id}-level" name="nivel"><option value="">Todas as formações</option><option>Licenciatura</option><option>Pós-graduação</option><option>Curso de curta duração</option></select><button class="button" type="submit">Encontrar curso <span>↗</span></button></form>`;
const cta=()=>`<section class="cta wrap reveal"><div><span class="eyebrow">UM NOVO CAPÍTULO COMEÇA AQUI</span><h2>O futuro tem espaço<br>para a <em>sua próxima ideia.</em></h2><p>Descubra o percurso que faz sentido para si.</p></div><div>${link('/cursos/','Encontre o seu curso')}${link('/ingresso/','Saiba como candidatar-se','text-link')}</div><span class="cta-star" aria-hidden="true">✳</span></section>`;
write('/','Conhecimento que aproxima futuros',`<section class="home-hero wrap"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> CONHECIMENTO SEM FRONTEIRAS · ANGOLA</div><h1>O seu futuro<br>começa <em>aqui.</em><span class="hero-arrow">↗</span></h1><p>Aprender. Descobrir. Transformar.<br>Encontre o seu caminho e faça parte de uma nova perspectiva de ensino superior.</p><div class="hero-buttons">${link('/cursos/','Explore os cursos')}${link('/sobre/','Conheça o ISPAB','text-link')}</div><div class="hero-small"><span class="mini-symbol">✳</span><span>Mais do que escolher uma formação.<br><strong>Escolher quem quer ser.</strong></span></div></div><div class="hero-visual"><div class="hero-grid"></div><div class="hero-photo"><img src="/assets/hero.webp" alt="Estudantes partilhando ideias numa biblioteca" fetchpriority="high"><div class="hero-photo-caption">Grandes ideias começam com uma conexão. <span>↗</span></div></div><div class="hero-float"><span>✳</span><p>O próximo capítulo?<br><strong>É o seu.</strong></p></div><div class="hero-badge"><i></i> Conhecimento em movimento.</div><span class="hero-spark">✳</span><span class="hero-side">ENSINO · INVESTIGAÇÃO · COMUNIDADE</span></div></section><section class="finder wrap"><div class="finder-title"><span class="eyebrow">ENCONTRE A SUA PRÓXIMA POSSIBILIDADE</span><a href="/cursos/">Ver todos os cursos ↗</a></div>${searchBox()}<div class="finder-tags"><span>Explore por interesse:</span><a href="/cursos/?area=tecnologia">Tecnologia</a><a href="/cursos/?area=saude">Saúde</a><a href="/cursos/?area=gestao">Gestão</a><a href="/cursos/?area=engenharia">Engenharia</a></div></section><div class="marquee"><div>APRENDER <span>✳</span> CONECTAR <span>✳</span> DESCOBRIR <span>✳</span> TRANSFORMAR <span>✳</span> APRENDER <span>✳</span> CONECTAR <span>✳</span> DESCOBRIR <span>✳</span> TRANSFORMAR <span>✳</span></div></div><section class="quick-paths wrap" aria-label="Atalhos para o seu percurso"><a href="/ingresso/"><span>↗</span><div><strong>Quero estudar no ISPAB</strong><small>O primeiro passo começa aqui</small></div><b>↗</b></a><a href="/candidaturas/"><span>▤</span><div><strong>Já comecei a candidatura</strong><small>Retome o seu percurso</small></div><b>↗</b></a><a href="/login/"><span>◫</span><div><strong>Procuro o portal académico</strong><small>Entre no seu espaço de aprendizagem</small></div><b>↗</b></a></section><section class="section wrap"><div class="section-title reveal"><div><span class="eyebrow">01 / ENCONTRE A SUA ÁREA</span><h2>Muitos caminhos.<br><em>Um futuro que é seu.</em></h2></div><p>Comece pelo que desperta a sua curiosidade.<br>Conheça o nosso catálogo demonstrativo.</p></div><div class="areas-grid">${areas.map(a=>`<a class="area-card ${a.color} reveal" href="/cursos/?area=${a.id}"><span class="area-icon">${a.icon}</span><h3>${a.name}</h3><p>${a.description}</p><span class="area-bottom"><span>${courses.filter(c=>c.area===a.id).length} percursos de exemplo</span><span>↗</span></span></a>`).join('')}</div></section><section class="section soft-bg"><div class="wrap"><div class="section-title reveal"><div><span class="eyebrow">02 / CONHECIMENTO EM MOVIMENTO</span><h2>Qual vai ser o seu<br><em>próximo grande passo?</em></h2></div>${link('/cursos/','Explorar todos os cursos','text-link')}</div><div class="course-grid">${courses.filter(c=>c.featured).slice(0,3).map(courseCard).join('')}</div><p class="quiet-note">Catálogo ilustrativo · Oferta, modalidade e duração a confirmar pela instituição.</p></div></section><section class="section wrap split-feature"><div class="split-photo reveal"><img src="/assets/student.webp" alt="Estudantes celebrando a conclusão da sua formação" loading="lazy"><span class="photo-label">O SEU FUTURO.<br>AS SUAS POSSIBILIDADES. ↗</span></div><div class="reveal"><span class="eyebrow">03 / MUITO ALÉM DA SALA DE AULA</span><h2>Aprender é descobrir.<br><em>E também pertencer.</em></h2><p>O ensino superior é feito de perguntas, encontros e descobertas. Explore uma visão de comunidade onde os seus interesses encontram novas perspectivas.</p><ul class="check-list"><li>Trocas entre diferentes áreas do conhecimento</li><li>Projectos que aproximam teoria e prática</li><li>Uma jornada com espaço para crescer</li></ul>${link('/vida-academica/','Explore a vida académica','text-link')}</div></section><section class="blue-band"><div class="wrap"><span class="eyebrow">O PRIMEIRO PASSO NÃO PRECISA DE SER COMPLICADO</span><h2>Da curiosidade<br>à <span>sua candidatura.</span></h2><div class="steps-row">${[['01','Descubra o seu curso','Explore áreas, modalidades e percursos.'],['02','Prepare o próximo passo','Conheça as orientações para o ingresso.'],['03','Experimente a candidatura','Percorra o formulário demonstrativo.']].map(s=>`<div><span>${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></div>`).join('')}</div>${link('/ingresso/','Veja como começar','button white')}<span class="band-star" aria-hidden="true">✳</span></div></section><section class="section wrap"><div class="section-title"><div><span class="eyebrow">04 / IDEIAS PARA LEVAR CONSIGO</span><h2>Histórias que abrem<br><em>novas perspectivas.</em></h2></div>${link('/blog/','Blog da escola','text-link')}</div><div class="article-grid" data-school-blog-feed>${articles.slice(0,3).map(articleCard).join('')}</div></section>${cta()}`);
function articleCard(a){return `<article class="article-card reveal"><a href="/noticias/${a.id}/" tabindex="-1" aria-hidden="true"><img src="/assets/${a.image}.webp" alt="" loading="lazy"></a><span class="eyebrow">${a.category} · LEITURA DEMONSTRATIVA</span><h3><a href="/noticias/${a.id}/">${a.title}</a></h3><a class="text-link" href="/noticias/${a.id}/">Ler a história <span>↗</span></a></article>`}
const filters=`<aside class="filters" id="course-filters"><div class="filter-title"><h2>Filtrar cursos</h2><button type="button" id="clear-filters">Limpar</button></div><label>Área do conhecimento<select name="area" id="filter-area"><option value="">Todas as áreas</option>${areas.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><label>Nível de formação<select name="nivel" id="filter-level"><option value="">Todas as formações</option><option>Licenciatura</option><option>Pós-graduação</option><option>Curso de curta duração</option></select></label><fieldset><legend>Modalidade</legend>${['Presencial','Online','Híbrido'].map(m=>`<label class="check-option"><input type="checkbox" name="mode" value="${m}">${m}</label>`).join('')}</fieldset><label>Turno<select name="turno" id="filter-shift"><option value="">Todos os turnos</option><option>Diurno</option><option>Pós-laboral</option><option>Flexível</option></select></label><label>Unidade<select name="unidade" id="filter-unit"><option value="">Todas as unidades</option><option>Campus Académico</option><option>Campus Digital</option></select></label><div class="filter-help"><span>Não sabe por onde começar?</span><p>Compare percursos e descubra o que combina consigo.</p><a href="/ingresso/">Orientação para ingresso ↗</a></div></aside>`;
write('/cursos/','Encontre o seu curso',`${crumb('Cursos')}${pageHead('O SEU FUTURO COMEÇA COM UMA DESCOBERTA','Encontre o curso.<br><em>Imagine as possibilidades.</em>','Explore o catálogo, compare percursos e escolha o próximo passo com mais confiança.')}<section class="wrap catalogue-section"><div class="catalogue-top"><form id="catalog-search" class="search-input"><span>⌕</span><label class="sr-only" for="catalog-q">Pesquisar cursos</label><input type="search" id="catalog-q" placeholder="Pesquise por curso, tema ou competência"><button class="button small">Pesquisar</button></form><a href="/favoritos/" class="outline-button">♡ Favoritos <span data-favorite-count>0</span></a><a href="/comparar/" class="outline-button">⇄ Comparar <span data-compare-count>0</span></a></div>${notice()}<div class="catalogue-mobile-tools"><button class="outline-button" id="toggle-filters" aria-expanded="false" aria-controls="course-filters"><span>☷</span> Filtros <b id="mobile-filter-count" hidden>0</b><span class="filter-chevron">⌄</span></button><span>Encontre o percurso certo para si.</span></div><div class="catalogue-layout">${filters}<div class="catalogue-results"><div class="results-heading"><p id="results-count" aria-live="polite">${courses.length} cursos para explorar</p><label>Ordenar por <select id="sort-courses"><option value="featured">Destaques</option><option value="az">Nome A–Z</option><option value="duration">Menor duração</option></select></label></div><div id="active-filters"></div><div class="course-grid two-cols" id="course-results">${courses.map(courseCard).join('')}</div><div id="no-courses" class="empty-state" hidden><span>⌕</span><h2>Nenhum curso encontrado.</h2><p>Experimente outra palavra ou remova alguns filtros.</p><button class="button" id="empty-clear">Limpar filtros <span>↗</span></button></div></div></div></section><div id="compare-bar" class="compare-bar" hidden><span><strong data-compare-count>0</strong> cursos seleccionados</span><a class="button small" href="/comparar/">Comparar agora ↗</a></div>`,{active:'catalog'});
for(const c of courses){const area=areas.find(a=>a.id===c.area);const specs=getCourseSpecs(c);write('/cursos/'+c.id+'/',c.name,`${crumb(c.name,'<a href="/cursos/">Cursos</a><span>/</span>')}<section class="course-hero wrap"><div><div class="eyebrow">${area.name} · ${c.level}</div><h1>${c.name}</h1><p>${c.description}</p><div class="course-hero-meta"><span>◷ ${c.duration}</span><span>◎ ${c.mode}</span><span>☷ ${c.shift}</span></div><div class="course-code">EXEMPLO DE FORMAÇÃO <span>•</span> ${c.level} <span>•</span> ${area.name}</div><div class="hero-buttons">${link('/candidatura/?curso='+c.id,'Experimentar candidatura')}<button class="outline-button" data-favorite="${c.id}" aria-pressed="false">♡ Guardar curso</button></div><p class="quiet-note">Curso demonstrativo · Não constitui oferta oficial.</p></div><div class="course-hero-image"><img src="/assets/${c.image}.webp" alt="Ambiente académico ilustrativo" fetchpriority="high"><span>${area.icon}</span></div></section><nav class="course-subnav" aria-label="Conteúdos do curso"><div class="wrap"><a href="#apresentacao">Apresentação</a><a href="#competencias">Competências</a><a href="#plano">Plano de estudos</a><a href="#carreiras">Possibilidades de actuação</a><a href="#ingresso">Ingresso</a></div></nav><section class="section wrap course-detail-layout"><div><section id="apresentacao" class="detail-block"><span class="eyebrow">UM PERCURSO DE DESCOBERTAS</span><h2>Conheça o universo de<br><em>${c.name}.</em></h2><p>${c.description} Este percurso ilustrativo liga fundamentos da área à análise de problemas, ao trabalho em equipa e à construção de projectos.</p><p>A proposta valoriza uma aprendizagem progressiva, a capacidade de investigar e a aplicação do conhecimento em diferentes contextos.</p>${notice('Esta descrição e os conteúdos abaixo são exemplos editoriais. A aprovação, o reconhecimento e a disponibilidade deste curso no ISPAB não foram confirmados.')}</section><section id="competencias" class="detail-block course-competencies"><span class="eyebrow">DO CONHECIMENTO À PRÁTICA</span><h2>O que poderá desenvolver.</h2><p>Competências ilustrativas para ajudar a compreender a área.</p><ul class="competency-list">${specs.outcomes.map((item,i)=>`<li><span>0${i+1}</span><p>${item}</p><b aria-hidden="true">↗</b></li>`).join('')}</ul><div class="course-audience"><h3>É um caminho para si?</h3><p>${specs.audience}</p><span>Para começar</span><p>${specs.preparation}</p></div></section><section id="plano" class="detail-block"><span class="eyebrow">CONHECIMENTO EM CONSTRUÇÃO</span><h2>O que poderá explorar.</h2><p>Uma selecção ilustrativa de temas da área. Não corresponde a uma matriz curricular oficial.</p><div class="module-list">${c.modules.map((m,i)=>`<details${i===0?' open':''}><summary><span>0${i+1}</span>${m}<b>+</b></summary><p>${specs.modules[i].description}</p><span class="module-caption">Tema ilustrativo · Conteúdo sujeito a validação</span></details>`).join('')}</div></section><section class="detail-block course-method"><span class="eyebrow">UM PERCURSO COM ESTRUTURA</span><h2>Como poderá aprender.</h2><div class="method-grid"><article><span>◎</span><h3>Experiência de aprendizagem</h3><p>${specs.delivery} ${specs.practice}</p></article><article><span>✓</span><h3>Avaliação de exemplo</h3><p>${specs.assessment}</p></article></div><details class="resource-details"><summary>Recursos para a aprendizagem <span>+</span></summary><p>${specs.resources}</p><a class="text-link" href="/biblioteca/">Explorar a biblioteca ↗</a></details></section><section id="carreiras" class="detail-block"><span class="eyebrow">CONHECIMENTO QUE ABRE CAMINHOS</span><h2>Possibilidades de actuação.</h2><p>Exemplos de áreas relacionadas com a formação. O exercício profissional depende da habilitação, das regras e dos requisitos aplicáveis.</p><div class="career-tags">${c.careers.map(x=>`<span>↗ ${x}</span>`).join('')}</div></section><section id="ingresso" class="detail-block"><h2>Prepare a sua candidatura.</h2><p>Consulte o edital oficial e confirme habilitações exigidas, documentos, provas, vagas e calendário junto da instituição.</p>${link('/ingresso/','Conhecer as formas de ingresso','text-link')}<div class="entry-requirement"><span>▤</span><div><h3>Preparação de acesso</h3><p>${specs.access} Documentos, provas, taxas e prazos dependem do edital oficial.</p></div></div></section><section class="detail-block course-questions"><h2>Antes de escolher.</h2><div class="faq-list"><details><summary>O plano de estudos é oficial?<span>+</span></summary><p>Não. Estes temas mostram como o curso poderá ser apresentado. Matriz curricular, carga horária, créditos e qualificação final precisam de validação pelo ISPAB.</p></details><details><summary>Posso guardar esta informação?<span>+</span></summary><p>Sim. Pode guardar o curso nos favoritos, compará-lo com outros percursos ou descarregar uma ficha demonstrativa. Os favoritos ficam neste navegador.</p></details><details><summary>Como confirmar propinas, vagas e requisitos?<span>+</span></summary><p>Consulte o edital e os contactos oficiais da instituição. Esta prévia não anuncia vagas nem valores confirmados.</p></details></div></section></div><aside class="course-summary"><span class="eyebrow">O PERCURSO, NUM RELANCE</span><h3>${c.name}</h3><dl>${[['Formação',c.level],['Duração ilustrativa',c.duration],['Estrutura',specs.structure],['Idioma de exemplo',specs.language],['Modalidade',c.mode],['Turno',c.shift],['Unidade de exemplo',c.unit],['Propinas','A confirmar'],['Vagas e calendário','A confirmar']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${link('/candidatura/?curso='+c.id,'Explorar candidatura')}<button class="course-guide-button outline-button" data-course-guide="${c.id}">Descarregar ficha de exemplo <span>↓</span></button><label class="compare-label"><input type="checkbox" data-compare="${c.id}"> Adicionar à comparação</label><a href="/contactos/">Tem alguma dúvida? Prepare uma mensagem ↗</a></aside></section><aside class="course-mobile-action" data-course-action hidden aria-label="Atalho de candidatura"><div><small>CURSO DEMONSTRATIVO</small><strong>${c.name}</strong></div>${link('/candidatura/?curso='+c.id,'Candidatura','button small')}</aside><section class="section soft-bg"><div class="wrap"><div class="section-title"><div><span class="eyebrow">CONTINUE A DESCOBRIR</span><h2>Outros caminhos possíveis.</h2></div>${link('/cursos/','Ver catálogo','text-link')}</div><div class="course-grid">${courses.filter(x=>x.id!==c.id).sort((a,b)=>Number(b.area===c.area)-Number(a.area===c.area)).slice(0,3).map(courseCard).join('')}</div></div></section>`,{active:'course'})}
write('/favoritos/','Os meus cursos favoritos',`${crumb('Favoritos')}${pageHead('UM LUGAR PARA AS SUAS DESCOBERTAS','Guarde ideias.<br><em>Volte às possibilidades.</em>','Os seus cursos guardados ficam disponíveis neste navegador.')}<section class="wrap section"><div class="course-grid" id="saved-courses"></div><div id="saved-empty" class="empty-state"><span>♡</span><h2>O seu próximo favorito está por descobrir.</h2><p>Toque no coração de um curso para o guardar aqui.</p>${link('/cursos/','Explorar cursos')}</div></section>`,{active:'favorites'});
