write('/ingresso/','Como candidatar-se',`${crumb('Ingresso')}${pageHead('O SEU PRIMEIRO PASSO','Uma nova jornada.<br><em>Comece com confiança.</em>','Conheça o percurso de candidatura e prepare as perguntas certas para dar o próximo passo.',link('/candidatura/','Experimentar candidatura'))}<section class="wrap section"><div class="section-title"><div><span class="eyebrow">UM PERCURSO, DIFERENTES PONTOS DE PARTIDA</span><h2>Como quer <em>começar?</em></h2></div><p>Orientações gerais de ingresso.<br>Os critérios oficiais dependem do edital do ISPAB.</p></div><div class="info-grid">${[['01','Primeiro ingresso','Para quem pretende iniciar a primeira formação superior. Confirme as habilitações exigidas, as provas de acesso e o calendário.','Primeiro ingresso'],['02','Transferência','Para quem já frequenta uma instituição e pretende conhecer as condições de transferência e eventual equivalência.','Transferência'],['03','Segunda formação','Para quem já concluiu uma formação superior e procura um novo percurso. Confirme os procedimentos e a documentação.','Segunda formação']].map(s=>`<article class="info-card"><span class="big-number">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p>${link(s[3]==='Transferência'?'/percursos-de-ingresso/':'/candidatura/?via='+encodeURIComponent(s[3]),'Explorar esta opção','text-link')}</article>`).join('')}</div>${notice('Não há candidaturas oficiais abertas nesta prévia. A simulação não garante vaga, admissão, bolsa ou matrícula.')}</section><section class="soft-bg section"><div class="wrap split-text"><div><span class="eyebrow">ORGANIZE O PRÓXIMO PASSO</span><h2>Uma pequena lista.<br><em>Uma grande ajuda.</em></h2><p>Use a lista para preparar uma candidatura real. Confirme todos os requisitos nos canais institucionais.</p>${link('/preparar-candidatura/','Abrir a minha lista de preparação','text-link')}</div><ol class="numbered-list"><li><span>01</span><div><h3>Encontre a sua área</h3><p>Conheça o curso, a formação e as possibilidades.</p></div></li><li><span>02</span><div><h3>Leia as regras oficiais</h3><p>Verifique requisitos, documentação, provas e prazos.</p></div></li><li><span>03</span><div><h3>Prepare a documentação</h3><p>Tenha identificação e comprovativos de habilitações válidos.</p></div></li><li><span>04</span><div><h3>Reveja e acompanhe</h3><p>Use apenas os canais oficiais para concluir a candidatura real.</p></div></li></ol></div></section>${cta()}`);
write('/candidatura/','Candidatura online',`${crumb('Candidatura')}${pageHead('O PRÓXIMO CAPÍTULO É SEU','O seu caminho<br><em>começa com uma escolha.</em>','Explore a candidatura em três etapas. Pode guardar um rascunho e continuar neste navegador.')}<section class="wrap section application-layout"><aside class="application-aside"><span class="eyebrow">A SUA CANDIDATURA</span><ol class="wizard-steps"><li class="current" data-step-label="1"><span>1</span><div><strong>Escolha do curso</strong><small>O que quer aprender</small></div></li><li data-step-label="2"><span>2</span><div><strong>O seu perfil</strong><small>Informações de exemplo</small></div></li><li data-step-label="3"><span>3</span><div><strong>Rever e concluir</strong><small>Confirme cada detalhe</small></div></li></ol><div class="application-help"><h3>Ao seu ritmo.</h3><p>O rascunho é guardado apenas neste dispositivo. Esta candidatura é uma simulação e não é enviada à instituição.</p><a href="/ajuda/">Precisa de orientação? ↗</a></div></aside><div class="application-form"><div class="wizard-progress" aria-hidden="true"><span id="wizard-progress-bar"></span></div>${notice('Use dados fictícios. Não envie documentos pessoais. Esta experiência não cria uma candidatura oficial.')}<div id="draft-prompt" hidden></div><form id="application-form"><section data-step="1"><div class="step-heading"><span class="eyebrow">PASSO 01 DE 03</span><h2>Encontre a sua direcção.</h2><p>Seleccione o curso e o seu ponto de partida.</p></div><label>Curso de interesse <span>*</span><select id="apply-course" name="course" required><option value="">Seleccione um curso</option>${courses.map(c=>`<option value="${c.id}">${c.name} · ${c.level}</option>`).join('')}</select></label><div id="apply-course-info"></div><div class="form-row"><label>Forma de ingresso <span>*</span><select name="via" required><option value="">Seleccione</option><option>Primeiro ingresso</option><option>Transferência</option><option>Segunda formação</option><option>Formação contínua</option></select></label><label>Período de interesse <span>*</span><select name="period" required><option value="">Seleccione</option><option>Próximo período disponível</option><option>Quero apenas conhecer as opções</option></select></label></div></section><section data-step="2" hidden><div class="step-heading"><span class="eyebrow">PASSO 02 DE 03</span><h2>Conte-nos um pouco sobre si.</h2><p>Preencha com informações fictícias para experimentar o percurso.</p></div><label>Nome de exemplo <span>*</span><input name="name" required maxlength="100" autocomplete="off" placeholder="Ex.: Joana Exemplo"></label><div class="form-row"><label>E-mail de exemplo <span>*</span><input name="email" type="email" required maxlength="150" autocomplete="off" placeholder="joana@example.com"></label><label>Província de interesse <span>*</span><select name="province" required><option value="">Seleccione</option>${['Benguela','Bengo','Bié','Cabinda','Cuando','Cubango','Cuanza Norte','Cuanza Sul','Cunene','Huambo','Huíla','Icolo e Bengo','Luanda','Lunda Norte','Lunda Sul','Malanje','Moxico','Moxico Leste','Namibe','Uíge','Zaire','Outra / prefiro não indicar'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label>O que o motiva a explorar este curso?<textarea name="motivation" maxlength="1000" rows="4" placeholder="Partilhe uma ideia ou um objectivo (opcional)"></textarea></label><div class="checklist-box"><h3>Preparação para uma candidatura real</h3><p>Não faça upload de documentos nesta prévia. Numa candidatura oficial, confirme a lista de requisitos com a instituição.</p><label class="check-option"><input type="checkbox" name="checkId"> Sei que devo confirmar os documentos de identificação exigidos.</label><label class="check-option"><input type="checkbox" name="checkSchool"> Sei que devo confirmar os comprovativos de habilitações.</label></div></section><section data-step="3" hidden><div class="step-heading"><span class="eyebrow">PASSO 03 DE 03</span><h2>O próximo passo, com clareza.</h2><p>Reveja os seus dados antes de concluir a demonstração.</p></div><div id="application-review" class="review-card"></div><label class="check-option consent"><input type="checkbox" name="consent" required> Compreendo que esta candidatura é demonstrativa, fica guardada apenas neste navegador e não é enviada ao ISPAB.</label></section><p id="application-error" class="form-error" role="alert"></p><div class="form-controls"><button type="button" class="text-button" id="wizard-back" hidden>← Voltar</button><button type="button" class="text-button" id="save-draft">Guardar rascunho</button><button type="submit" class="button" id="wizard-next">Continuar <span>→</span></button></div></form><div id="application-success" hidden class="success-panel"></div></div></section>`,{active:'application'});
write('/candidaturas/','Acompanhar candidaturas',`${crumb('Área do candidato')}${pageHead('CADA PASSO, NO SEU LUGAR','A sua jornada.<br><em>Sempre por perto.</em>','Consulte os rascunhos e as candidaturas demonstrativas guardados neste navegador.')}<section class="section wrap">${notice('Estes registos são locais e demonstrativos. Não representam inscrição, análise, admissão ou matrícula no ISPAB.')}<div id="candidate-records"></div><div class="section-title top-space"><div><h2>Continuar a descobrir.</h2><p>A sua escolha merece tempo e perspectiva.</p></div>${link('/cursos/','Explorar cursos','text-link')}</div></section>`,{active:'candidates'});
write('/login/','Entrar no portal',`${crumb('Acesso ao portal')}<section class="login-layout wrap section"><div class="login-story"><span class="eyebrow">UM LUGAR PARA A SUA JORNADA</span><h1>O seu campus.<br><em>Mais perto de si.</em></h1><p>Disciplinas, horários, candidaturas e serviços. Uma visão organizada da experiência académica.</p><img src="/assets/hero.webp" alt="Estudantes a colaborar na biblioteca"><span class="login-star">✳</span></div><div class="login-card"><div class="login-icon">◫</div><h2>Bem-vindo ao ISPAB.</h2><p>A sua conta académica, num só lugar.</p><section class="portal-primary-choice" data-site-scope="student-access"><span class="eyebrow">ESTUDANTES</span><h3>A sua vida académica, aqui.</h3><p>Consulte as suas disciplinas, notas e horários com a conta da escola.</p><a class="button" href="/portal/">Abrir portal do estudante <span>↗</span></a><a class="text-link student-account-link" data-student-login aria-disabled="true">Entrar com a minha conta <span>↗</span></a></section><div class="portal-staff-choice" data-site-scope="staff-access"><h3>Docentes e administração</h3><p>Entre no sistema de gestão com o seu perfil institucional.</p></div><a class="button auth-button" data-siga-login aria-disabled="true">Entrar no SIGA Plus <span>↗</span></a><p class="input-hint" data-siga-status>O acesso institucional será disponibilizado após configurar o endereço do SIGA Plus.</p><div class="or"><span>ou explore a experiência</span></div><a class="outline-button demo-login" href="/portal/?demo=1">Explorar portal demonstrativo <span>→</span></a><div class="login-note"><span>ⓘ</span><p>O portal contém um perfil fictício e dados académicos de exemplo. As informações oficiais são consultadas no SIGA Plus.</p></div><div class="login-bottom"><a href="/candidaturas/">Sou candidato</a><a href="/ajuda/">Preciso de ajuda ↗</a></div></div></section><section class="wrap portal-access-resources" data-site-scope="portal-resources" aria-label="Serviços para a comunidade"><h2>O apoio certo para cada etapa.</h2><div><a href="/calendario/"><strong>Calendário académico <span>↗</span></strong><small>Planeie as próximas etapas.</small></a><a href="/biblioteca/"><strong>Biblioteca <span>↗</span></strong><small>Encontre recursos para estudar.</small></a><a href="/servicos/secretaria/"><strong>Secretaria académica <span>↗</span></strong><small>Documentos e orientações.</small></a><a href="/apoio-ao-estudante/"><strong>Apoio ao estudante <span>↗</span></strong><small>Saiba com quem falar.</small></a></div><details><summary>Precisa de recuperar o acesso?</summary><p>No ecrã de entrada, escolha a recuperação de palavra-passe. Se a sua conta usa Google, utilize o mesmo método. Para contas sem vínculo à escola, contacte a secretaria.</p></details></section>`,{active:'login'});
// Institutional and student-service pages.
write('/sobre/','Conheça o ISPAB',`${crumb('O ISPAB')}${pageHead('CONHECIMENTO QUE APROXIMA FUTUROS','Uma nova perspectiva.<br><em>Muitas possibilidades.</em>','ISPAB · Angola. Uma experiência digital pensada para aproximar formação, pessoas e conhecimento.')}<section class="wrap section split-feature"><div class="split-photo"><img src="/assets/campus.webp" alt="Arquitectura universitária ilustrativa"><span class="photo-label">APRENDER É UM<br>MOVIMENTO CONTÍNUO. ↗</span></div><div><span class="eyebrow">UMA EXPERIÊNCIA CENTRADA EM PESSOAS</span><h2>Do primeiro interesse<br>ao <em>próximo capítulo.</em></h2><p>Este website organiza a experiência do ISPAB em torno de quem aprende: descobrir uma área, compreender o ingresso, acompanhar o percurso e encontrar serviços.</p><p>A visão combina ensino, investigação e relação com a comunidade. A história institucional, os órgãos de gestão, os reconhecimentos e a oferta oficial serão incorporados após validação.</p>${link('/sobre-o-projecto/','Conhecer esta prévia','text-link')}</div></section><section class="section soft-bg"><div class="wrap"><div class="section-title"><h2>Ideias que orientam<br><em>esta experiência.</em></h2></div><div class="info-grid">${[['◎','Pessoas no centro','Uma navegação clara para estudantes, candidatos, docentes e comunidade.'],['✳','Conhecimento em movimento','Espaço para descobrir, questionar, investigar e construir novas perspectivas.'],['↗','Possibilidades de futuro','Percursos de aprendizagem ligados aos interesses e aos próximos passos de cada pessoa.']].map(x=>`<article class="info-card"><span class="area-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section>${cta()}`);
write('/vida-academica/','Vida académica',`${crumb('Vida académica')}${pageHead('APRENDER TAMBÉM É PERTENCER','O campus é feito<br><em>de encontros.</em>','Trocas, projectos, perguntas e descobertas. Explore possibilidades para enriquecer a sua experiência.')}<section class="section wrap"><div class="editorial-image"><img src="/assets/community.webp" alt="Pessoas reunidas num evento de partilha de conhecimento"><span>UM CONVITE A PARTICIPAR. ↗</span></div><div class="info-grid top-space">${[['Grupos e iniciativas','Encontre temas em comum e descubra o valor de aprender com outras pessoas.','/eventos/','Explorar a agenda'],['Bem-estar e acolhimento','Conheça orientações para organizar a rotina, procurar apoio e participar com autonomia.','/apoio-ao-estudante/','Encontrar apoio'],['Ideias com impacto','Explore a ligação entre estudo, investigação e desafios da comunidade.','/investigacao/','Conhecer possibilidades']].map(x=>`<article class="info-card"><h3>${x[0]}</h3><p>${x[1]}</p>${link(x[2],x[3],'text-link')}</article>`).join('')}</div></section><section class="soft-bg section"><div class="wrap"><div class="section-title"><h2>Leve uma nova<br><em>perspectiva consigo.</em></h2></div><div class="article-grid">${articles.filter(a=>['aprender-em-comunidade','organizar-rotina','como-escolher-o-curso'].includes(a.id)).map(articleCard).join('')}</div></div></section>${cta()}`);
write('/campus/','Espaços e campus',`${crumb('Campus')}${pageHead('ESPAÇOS PARA PENSAR ALÉM','Onde as ideias<br><em>encontram espaço.</em>','Uma visão ilustrativa de ambientes para aprender, partilhar e construir.')}<section class="section wrap">${notice('As fotografias e os ambientes são ilustrativos e não representam instalações verificadas do ISPAB. Endereço, visitas e unidades serão publicados após confirmação.')}<div class="space-grid">${[['campus','Espaços de aprendizagem','Ambientes pensados para o encontro entre teoria, prática e novas perguntas.'],['teacher','Salas e laboratórios','Possibilidades para experimentar, investigar e aprender em colaboração.'],['hero','Biblioteca e estudo','Um lugar para explorar referências e aprofundar o conhecimento.'],['community','Convívio e comunidade','Encontros que ampliam a experiência para além das aulas.']].map(x=>`<article><img src="/assets/${x[0]}.webp" alt="${x[1]} — imagem ilustrativa" loading="lazy"><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</div></section>${cta()}`);
write('/servicos/','Serviços académicos',`${crumb('Serviços')}${pageHead('O APOIO CERTO, NO MOMENTO CERTO','Mais simples.<br><em>Mais perto de si.</em>','Encontre orientações, recursos e caminhos para a sua experiência académica.')}<section class="wrap section"><div class="service-intro"><div><span class="eyebrow">ENCONTRE O APOIO CERTO</span><h2>O que precisa de fazer hoje?</h2></div><p>Escolha um serviço para conhecer as orientações<br>e os próximos passos disponíveis nesta prévia.</p></div><div class="service-grid">${services.map(s=>`<a class="service-card" href="${s.url}"><span>${s.icon}</span><h2>${s.title}</h2><p>${s.text}</p><b>Explorar serviço ↗</b></a>`).join('')}</div></section>${cta()}`);
const simplePages=[
['/servicos/secretaria/','Secretaria académica','ORIENTAÇÃO PARA O SEU PERCURSO','Cada etapa,<br><em>bem acompanhada.</em>','Encontre orientações para preparar pedidos e acompanhar a sua jornada académica.','O que pode organizar',[['Declarações e comprovativos','Confirme com a instituição os tipos de documentos disponíveis, os critérios de emissão e os prazos aplicáveis.'],['Matrícula e percurso','Reúna as dúvidas sobre inscrição, renovação de matrícula, mudança de turno e equivalências.'],['Requerimentos','Experimente um pedido demonstrativo e acompanhe o seu registo local no portal.']],'/portal/pedidos/','Explorar requerimentos'],
['/apoio-ao-estudante/','Apoio ao estudante','NINGUÉM APRENDE SOZINHO','Há sempre espaço<br><em>para pedir apoio.</em>','Uma experiência académica mais acolhedora começa por saber onde procurar orientação.','Encontre o seu ponto de apoio',[['Orientação académica','Organize as suas dúvidas sobre o percurso, a rotina de estudo e os próximos passos. A secretaria pode indicar o canal institucional adequado.'],['Acessibilidade e inclusão','Identifique barreiras de acesso, necessidades de adaptação e recursos que apoiam a participação. As medidas disponíveis devem ser confirmadas com a instituição.'],['Rotina e bem-estar','Reserve tempo para descanso, alimentação e relações de apoio. Se precisar de acompanhamento especializado, procure um serviço de saúde qualificado.']],'/contactos/?assunto=Apoio%20ao%20estudante','Preparar uma mensagem'],
['/carreiras/','Carreiras e estágios','O CONHECIMENTO ENCONTRA O MUNDO','O próximo passo<br><em>também se prepara.</em>','Ideias práticas para explorar áreas de actuação e desenvolver a sua apresentação profissional.','Prepare o seu caminho',[['Construa o seu CV','Organize formação, competências e projectos com exemplos concretos. Adapte o currículo ao objectivo e mantenha as informações claras e actualizadas.'],['Dê visibilidade aos projectos','Um portefólio pode reunir trabalhos de estudo, iniciativas e desafios que ajudaram a desenvolver competências. Peça autorização antes de expor trabalhos de terceiros.'],['Conheça a área','Pesquise organizações, converse com profissionais e confirme a legitimidade das oportunidades. Esta prévia não publica vagas ou estágios oficiais.']],'/cursos/','Explorar percursos de formação'],
['/investigacao/','Investigação e extensão','PERGUNTAS QUE ABREM CAMINHOS','Conhecimento em diálogo<br><em>com a sociedade.</em>','Uma visão de ensino superior que aproxima perguntas, investigação e desafios da comunidade.','Explore possibilidades',[['Iniciação à investigação','Aprenda a formular perguntas, analisar fontes e organizar uma investigação com rigor e responsabilidade.'],['Projectos interdisciplinares','Cruze perspectivas de diferentes áreas para compreender melhor um problema e desenvolver soluções fundamentadas.'],['Extensão e comunidade','Explore como o conhecimento pode dialogar com necessidades locais. Projectos e parcerias reais serão apresentados após validação institucional.']],'/biblioteca/','Encontrar referências abertas'],
['/bolsas/','Bolsas e apoios','PLANEIE O SEU FUTURO','Mais informação.<br><em>Melhores decisões.</em>','Saiba que perguntas fazer ao explorar bolsas, apoios e condições de acesso à formação.','O que confirmar antes de avançar',[['Critérios e elegibilidade','Consulte o regulamento oficial do apoio: quem pode candidatar-se, documentos exigidos, compatibilidades e critérios de selecção.'],['Calendário e condições','Confirme as datas, os montantes, as responsabilidades, a duração e as condições de manutenção do apoio.'],['Canais oficiais','Em Angola, pode consultar informação pública no INAGBE. A existência de uma bolsa para o ISPAB ou para um curso específico precisa de confirmação.']],'/contactos/?assunto=Bolsas%20e%20apoios','Preparar pedido de informação']
];
for(const [url,title,label,h,desc,sub,items,buttonUrl,buttonText] of simplePages)write(url,title,`${crumb(title)}${pageHead(label,h,desc)}<section class="wrap section"><div class="section-title"><h2>${sub}.</h2></div><div class="info-grid">${items.map((x,i)=>`<article class="info-card"><span class="big-number">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div><div class="inline-cta"><p>Transforme a informação no seu próximo passo.</p>${link(buttonUrl,buttonText)}</div>${url==='/bolsas/'?`${link('/planear-custos/','Planear os meus custos','text-link')}<p class="resource-link">Recurso externo: <a href="https://www.inagbe.gov.ao/" target="_blank" rel="noopener">INAGBE — Instituto Nacional de Gestão de Bolsas de Estudo ↗</a></p>${notice('Não há bolsas, descontos ou condições financeiras anunciados pelo ISPAB nesta prévia.')}`:''}</section>${cta()}`);
write('/biblioteca/','Biblioteca e recursos',`${crumb('Biblioteca')}${pageHead('CURIOSIDADE SEM FRONTEIRAS','O conhecimento<br><em>está à sua espera.</em>','Descubra fontes abertas e ferramentas para pesquisar, ler e aprender.')}<section class="section wrap"><div class="section-title"><h2>Abra uma nova<br><em>janela de conhecimento.</em></h2><p>Recursos externos de acesso público.<br>A disponibilidade depende de cada plataforma.</p></div><div class="resource-grid">${[['DOAJ','Artigos científicos','Directório de revistas de acesso aberto em diversas áreas.','https://doaj.org/','▤'],['SciELO','Investigação em acesso aberto','Biblioteca de publicações científicas, incluindo conteúdos em português.','https://scielo.org/','◎'],['MIT OpenCourseWare','Materiais de aprendizagem','Recursos de disciplinas e materiais de estudo disponibilizados pelo MIT.','https://ocw.mit.edu/','⌘'],['OpenStax','Livros e fundamentos','Livros de estudo abertos para explorar conceitos de diferentes áreas.','https://openstax.org/','▥']].map(x=>`<article class="resource-card"><span>${x[4]}</span><div class="eyebrow">${x[1]}</div><h2>${x[0]}</h2><p>${x[2]}</p><a class="text-link" href="${x[3]}" target="_blank" rel="noopener">Explorar recurso <span>↗</span></a></article>`).join('')}</div><div class="study-guide"><h2>Antes de citar, investigue a fonte.</h2><p>Verifique autoria, data, método e contexto. Distinga opinião de evidência e consulte as orientações de referência bibliográfica do seu curso.</p>${link('/noticias/organizar-rotina/','Organizar a rotina de estudo','text-link')}</div></section>`);
function eventCard(e){return `<article class="event-card"><div class="date-block"><strong><time datetime="${e.date}">${e.day}</time></strong><span>${e.month}</span></div><div><span class="eyebrow">${e.category} · EVENTO ILUSTRATIVO</span><h3>${e.title}</h3><p>${e.description}</p><div class="event-meta"><span>◷ ${e.time}</span><span>◎ ${e.place}</span></div></div><button class="outline-button" data-calendar="${e.id}" aria-label="Descarregar ${esc(e.title)} para a agenda — evento demonstrativo">Guardar na agenda <span>↗</span></button></article>`}
for(const url of ['/eventos/','/calendario/'])write(url,url==='/eventos/'?'Eventos':'Calendário académico',`${crumb(url==='/eventos/'?'Eventos':'Calendário')}${pageHead('ENCONTROS QUE ABREM PERSPECTIVAS',url==='/eventos/'?'Uma ideia.<br><em>Um novo encontro.</em>':'O seu tempo.<br><em>Novas possibilidades.</em>','Explore uma agenda de exemplo e experimente guardar actividades no seu calendário.')}<section class="wrap section">${notice('Agenda demonstrativa de Novembro de 2026. Não são eventos, prazos ou actividades oficiais do ISPAB.')}<div class="calendar-heading"><h2>Novembro de 2026</h2><span class="tag">Fuso horário de Angola · WAT (UTC+1)</span></div><div class="events-list">${events.map(eventCard).join('')}</div></section>`);
write('/noticias/','Notícias e histórias',`${crumb('Notícias')}${pageHead('IDEIAS PARA LEVAR CONSIGO','Uma nova leitura.<br><em>Uma nova perspectiva.</em>','Orientações, histórias e ideias para a sua jornada académica. Conteúdo editorial demonstrativo.')}<section class="section wrap"><div class="article-grid">${articles.map(articleCard).join('')}</div></section>`);
for(const a of articles)write('/noticias/'+a.id+'/',a.title,`${crumb(a.category,'<a href="/noticias/">Notícias</a><span>/</span>')}<article class="article-detail wrap"><header class="article-header"><span class="eyebrow">${a.category} · CONTEÚDO EDITORIAL DEMONSTRATIVO</span><h1>${a.title}</h1><p>${a.intro}</p><span class="article-byline">Redacção do projecto · <time datetime="2026-10-20">20 de Outubro de 2026</time> · 3 min de leitura</span></header><img class="article-cover" src="/assets/${a.image}.webp" alt="Ambiente académico ilustrativo"><div class="article-text">${a.sections.map(s=>`<section><h2>${s[0]}</h2><p>${s[1]}</p></section>`).join('')}<div class="article-share"><button class="outline-button" data-copy-link>Copiar link <span>↗</span></button>${link('/noticias/','Continuar a ler','text-link')}</div></div></article>${cta()}`);
write('/ajuda/','Central de ajuda',`${crumb('Central de ajuda')}${pageHead('COMO PODEMOS AJUDAR?','Boas perguntas.<br><em>Respostas claras.</em>','Encontre orientações sobre cursos, candidaturas e a experiência do portal.')}<section class="wrap section faq-layout"><aside><h2>Encontre o que precisa.</h2><p>Pesquise uma palavra nas perguntas frequentes.</p><label class="search-input"><span>⌕</span><input id="faq-search" type="search" placeholder="Ex.: candidatura" aria-label="Pesquisar perguntas"></label><div class="help-box"><h3>Ainda tem dúvidas?</h3><p>Prepare uma mensagem com a sua questão.</p>${link('/contactos/','Ir para contactos','text-link')}</div></aside><div id="faq-list" class="faq-list">${faqs.map((q,i)=>`<details${i===0?' open':''}><summary>${q[0]}<span>+</span></summary><p>${q[1]}</p></details>`).join('')}<p id="faq-empty" hidden>Nenhuma resposta encontrada. Experimente outra palavra.</p></div></section>`,{active:'help'});
write('/contactos/','Contactos',`${crumb('Contactos')}${pageHead('UMA CONVERSA PODE ABRIR CAMINHOS','Vamos encontrar<br><em>o próximo passo.</em>','Organize a sua questão para a instituição. Nesta prévia, pode preparar e descarregar uma mensagem.')}<section class="section wrap contact-layout"><aside><h2>Mais perto<br>da informação certa.</h2><p>Os contactos, o endereço e os horários oficiais do ISPAB em Angola ainda precisam de confirmação.</p><div class="contact-option"><span>◎</span><div><h3>Informação institucional</h3><p>Contactos oficiais a validar.</p></div></div><div class="contact-option"><span>↗</span><div><h3>Cursos e ingresso</h3><a href="/ingresso/">Consulte as orientações de ingresso</a></div></div><div class="contact-option"><span>◫</span><div><h3>Serviços académicos</h3><a href="/servicos/">Encontre um serviço</a></div></div></aside><form class="contact-form" id="contact-form"><h2>Prepare a sua mensagem.</h2><p>Este formulário gera um ficheiro no seu dispositivo. Não envia e-mail nem abre um pedido institucional.</p><div class="form-row"><label>Nome de exemplo <input name="name" required maxlength="100" placeholder="O seu nome de exemplo"></label><label>E-mail de exemplo <input name="email" type="email" required maxlength="150" placeholder="nome@example.com"></label></div><label>Assunto <select name="subject" required><option value="">Seleccione</option><option>Cursos e ingresso</option><option>Bolsas e apoios</option><option>Apoio ao estudante</option><option>Serviços académicos</option><option>Outro assunto</option></select></label><label>A sua mensagem <textarea name="message" required minlength="10" maxlength="3000" rows="5" placeholder="Como podemos ajudar? Use informação fictícia nesta demonstração."></textarea></label><button class="button" type="submit">Descarregar mensagem <span>↓</span></button><p class="input-hint">Nenhuma mensagem é enviada à instituição.</p></form></section>`,{active:'contact'});
write('/pesquisa/','Pesquisar no site',`${crumb('Pesquisa')}${pageHead('ENCONTRE UM NOVO CAMINHO','O que procura<br><em>está mais perto.</em>','Pesquise cursos, orientações e serviços num só lugar.')}<section class="wrap section site-search-section"><form class="search-input" id="site-search-form"><span>⌕</span><label class="sr-only" for="site-query">Pesquisar no site</label><input id="site-query" type="search" placeholder="Experimente: enfermagem, biblioteca, candidatura..."><button class="button small">Pesquisar <span>↗</span></button></form><p id="site-results-count" aria-live="polite"></p><div id="site-results"></div></section>`,{active:'search'});
// Portal: all academic records below are illustrative; no institution backend.
function portalShell(key,title,body){return `<a class="skip-link" href="#main">Saltar para o conteúdo</a><aside class="portal-sidebar"><a class="brand" href="/">${logo}</a><span class="portal-label">PORTAL ACADÉMICO</span><nav aria-label="Menu do portal">${portalNav.map(([id,label,icon])=>`<a class="${id===key?'active':''}" href="/portal/${id?id+'/':''}"><span>${icon}</span>${label}${id===key?'<b>•</b>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="/ajuda/">ⓘ Central de ajuda ↗</a><a href="/">↗ Voltar ao website</a><a href="/signout-with-chatgpt?return_to=%2Flogin%2F" target="_top">⇥ Terminar sessão</a></div><div class="sidebar-profile"><span>JE</span><div><strong>Joana Exemplo</strong><small>Perfil demonstrativo</small></div><a href="/portal/perfil/" aria-label="Ver perfil">⌄</a></div></aside><div class="portal-main"><header class="portal-header"><button class="portal-menu icon-button" aria-label="Abrir menu do portal" aria-expanded="false">☰</button><div><span>O SEU ESPAÇO ACADÉMICO</span><p>${title}</p></div><div class="portal-header-right"><a href="/pesquisa/" aria-label="Pesquisar">⌕</a><button class="icon-button" id="portal-notifications" aria-label="Ver avisos demonstrativos">♧<i></i></button><span class="profile-small">JE</span></div></header><div class="demo-strip"><span>◉ Modo de demonstração</span><p>Perfil e dados fictícios · Sem ligação ao sistema académico</p><a href="/sobre-o-projecto/">Saiba mais ↗</a></div><main id="main" class="portal-content"><div class="portal-page-title"><div><div class="eyebrow">ISPAB / PORTAL ACADÉMICO</div><h1>${title}</h1></div><span class="semester-pill">2026 / 2027 · Exemplo</span></div>${body}</main><footer class="portal-footer"><span>ISPAB · Portal demonstrativo</span><a href="/privacidade/">Dados guardados apenas neste navegador ↗</a></footer></div>`}
const subjects=[['Programação I','Eng. Informática','2.ª feira','08:00 – 10:00','Sala A1',16,92],['Matemática I','Eng. Informática','3.ª feira','10:15 – 12:15','Sala B2',14,88],['Introdução à Informática','Eng. Informática','4.ª feira','08:00 – 10:00','Laboratório 1',17,96],['Comunicação Académica','Formação transversal','5.ª feira','14:00 – 16:00','Sala A3',15,90]];
function portalWrite(key,title,body){write('/portal/'+(key?key+'/':''),title,portalShell(key,title,body),{portal:true,active:'portal-'+(key||'home')})}
portalWrite('','Visão geral',`<section class="portal-welcome"><div><span class="eyebrow">CADA DIA, UMA NOVA POSSIBILIDADE.</span><h2>Olá, Joana <span>✳</span><br>Vamos mais longe?</h2><p>A sua jornada académica, organizada num só lugar.</p><a href="/portal/disciplinas/" class="button white small">Ver as minhas disciplinas <span>↗</span></a></div><div class="welcome-art"><span>✳</span><div class="welcome-note">O próximo passo<br><strong>começa consigo.</strong></div></div></section><div class="stat-grid">${[['▤','4','Disciplinas de exemplo','blue'],['▥','15,5 / 20','Média ilustrativa','purple'],['◷','8 h','Aulas semanais de exemplo','lime'],['↗','0','Candidaturas locais','sand']].map((s,i)=>`<article class="stat-card"><span class="stat-icon ${s[3]}">${s[0]}</span><strong ${i===3?'data-application-count':''}>${s[1]}</strong><p>${s[2]}</p></article>`).join('')}</div><div class="dashboard-columns"><section class="portal-panel"><div class="panel-title"><h2>A sua semana</h2><a href="/portal/horarios/">Ver horário ↗</a></div>${subjects.slice(0,3).map((s,i)=>`<div class="class-row"><span class="class-day">${['SEG','TER','QUA'][i]}<strong>${s[3].split(' – ')[0]}</strong></span><div><h3>${s[0]}</h3><p>${s[4]} · Horário ilustrativo</p></div><span class="class-arrow">↗</span></div>`).join('')}</section><section class="portal-panel"><div class="panel-title"><h2>Acessos rápidos</h2><span>↗</span></div><div class="quick-grid">${[['/portal/notas/','▥','Notas e frequência'],['/portal/documentos/','▧','Documentos'],['/portal/pedidos/','⊕','Requerimentos'],['/candidatura/','↗','Nova candidatura']].map(s=>`<a href="${s[0]}"><span>${s[1]}</span>${s[2]} <b>↗</b></a>`).join('')}</div></section></div><section class="portal-panel"><div class="panel-title"><h2>No radar da comunidade</h2><a href="/eventos/">Ver agenda ↗</a></div><div class="portal-events">${events.slice(0,2).map(e=>`<div><span class="date-block"><strong>${e.day}</strong><span>${e.month}</span></span><div><h3>${e.title}</h3><p>Evento demonstrativo · ${e.time}</p></div><button class="icon-button" data-calendar="${e.id}" aria-label="Guardar ${e.title}">↗</button></div>`).join('')}</div></section>`);
portalWrite('disciplinas','As minhas disciplinas',`<div class="portal-info">Percurso ilustrativo: Engenharia Informática · 1.º ano. Estes dados não são um registo académico.</div><div class="subject-grid">${subjects.map((s,i)=>`<article class="subject-card"><div class="subject-top ${['blue','purple','lime','sand'][i]}"><span>0${i+1}</span><b>↗</b></div><span class="eyebrow">DISCIPLINA DEMONSTRATIVA</span><h2>${s[0]}</h2><p>${s[1]}</p><div class="subject-meta"><span>◷ ${s[2]}</span><span>${s[3]}</span></div><button class="text-link text-button" data-subject="${i}">Explorar conteúdos <span>↗</span></button></article>`).join('')}</div>`);
portalWrite('notas','Notas e frequência',`<div class="portal-info">Notas e presenças fictícias para demonstrar a consulta académica. Não é uma pauta oficial.</div><div class="stat-grid three-stats"><article class="stat-card"><span class="stat-icon blue">▥</span><strong>15,5 / 20</strong><p>Média ilustrativa</p></article><article class="stat-card"><span class="stat-icon lime">✓</span><strong>91,5%</strong><p>Frequência ilustrativa</p></article><article class="stat-card"><span class="stat-icon purple">▤</span><strong>4</strong><p>Disciplinas no exemplo</p></article></div><section class="portal-panel"><div class="panel-title"><h2>Desempenho por disciplina</h2><button class="outline-button small" id="download-grades">Exportar exemplo ↓</button></div><div class="table-scroll"><table><thead><tr><th>Disciplina</th><th>Nota de exemplo</th><th>Frequência</th><th>Registo</th></tr></thead><tbody>${subjects.map(s=>`<tr><td><strong>${s[0]}</strong><small>1.º ano · 1.º semestre</small></td><td><span class="grade">${s[5]}<small>/ 20</small></span></td><td><div class="attendance"><span style="width:${s[6]}%"></span></div><small>${s[6]}%</small></td><td><span class="status blue">Ilustrativo</span></td></tr>`).join('')}</tbody></table></div></section>`);
portalWrite('horarios','O meu horário',`<div class="portal-info">Horário semanal ilustrativo. Para consultar aulas reais, utilize os canais académicos oficiais.</div><section class="portal-panel"><div class="panel-title"><h2>Semana de exemplo</h2><div><button class="segment active" data-schedule="grid">Semana</button><button class="segment" data-schedule="list">Lista</button></div></div><div id="schedule-grid" class="table-scroll"><table class="schedule"><thead><tr><th>Horário</th>${['Segunda','Terça','Quarta','Quinta','Sexta'].map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${['08:00 – 10:00','10:15 – 12:15','14:00 – 16:00'].map((t,i)=>`<tr><th>${t}</th>${[0,1,2,3,4].map(d=>{const match=subjects.findIndex((s,si)=>[0,1,2,3][si]===d&&s[3]===t);return `<td>${match>=0?`<div class="schedule-class ${['blue','purple','lime','sand'][match]}"><strong>${subjects[match][0]}</strong><span>${subjects[match][4]}</span></div>`:'<span class="schedule-dash">—</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div id="schedule-list" hidden>${subjects.map(s=>`<div class="class-row"><span class="class-day">${s[2]}<strong>${s[3]}</strong></span><div><h3>${s[0]}</h3><p>${s[4]} · Exemplo</p></div></div>`).join('')}</div></section>`);
portalWrite('candidaturas','As minhas candidaturas',`${notice('Rascunhos e candidaturas desta demonstração são guardados apenas neste navegador e não são enviados à instituição.')}<div id="candidate-records"></div><div class="inline-cta"><p>Pronto para explorar um novo percurso?</p>${link('/candidatura/','Nova candidatura demonstrativa')}</div>`);
portalWrite('financeiro','Informação financeira',`<div class="portal-info">Este painel é ilustrativo. Não representa dívidas ou pagamentos reais e não permite efectuar transacções.</div><div class="stat-grid three-stats"><article class="stat-card"><span class="stat-icon blue">◈</span><strong>— Kz</strong><p>Valores oficiais a confirmar</p></article><article class="stat-card"><span class="stat-icon lime">✓</span><strong>Sem cobrança</strong><p>Esta demonstração não cobra propinas</p></article><article class="stat-card"><span class="stat-icon purple">ⓘ</span><strong>Orientação</strong><p>Procure os canais oficiais da instituição</p></article></div><section class="portal-panel"><div class="panel-title"><h2>Como será a consulta financeira</h2><span class="status">Prévia</span></div><div class="table-scroll"><table><thead><tr><th>Descrição</th><th>Período</th><th>Valor</th><th>Estado</th></tr></thead><tbody>${['Propina mensal','Taxa de matrícula','Serviços académicos'].map((x,i)=>`<tr><td><strong>${x}</strong><small>Categoria ilustrativa</small></td><td>A confirmar</td><td>— Kz</td><td><span class="status">Sem dados oficiais</span></td></tr>`).join('')}</tbody></table></div><div class="finance-note"><h3>Antes de efectuar um pagamento</h3><p>Confirme a tabela de propinas, a referência bancária e os prazos directamente com a instituição. Este site não gera referências nem solicita dados bancários.</p>${link('/contactos/?assunto=Serviços%20académicos','Preparar pedido de informação','text-link')}</div></section>`);
portalWrite('documentos','Documentos e comprovativos',`<div class="portal-info">Apenas modelos de consulta. Os ficheiros descarregados são claramente marcados como exemplos sem validade académica.</div><div class="document-grid">${[['percurso','Resumo do percurso','Dados académicos demonstrativos organizados num ficheiro de texto.'],['notas','Resumo de notas','Um exemplo de consulta para conhecer a estrutura do portal.'],['candidaturas','As minhas candidaturas locais','Exporte os registos da demonstração guardados neste navegador.']].map(s=>`<article class="portal-panel document-card"><span class="document-icon">▧</span><h2>${s[1]}</h2><p>${s[2]}</p><span class="status">Modelo sem validade</span><button class="outline-button" data-document="${s[0]}">Descarregar exemplo <span>↓</span></button></article>`).join('')}</div><section class="portal-panel top-space"><div class="panel-title"><h2>Precisa de um documento oficial?</h2></div><p class="muted">A emissão real depende da secretaria académica, dos requisitos e dos procedimentos institucionais.</p><a class="text-link" href="/servicos/secretaria/">Consultar orientações da secretaria <span>↗</span></a></section>`);
portalWrite('pedidos','Requerimentos e pedidos',`<div class="portal-info">Crie e acompanhe pedidos demonstrativos neste navegador. Nenhum pedido é enviado ao ISPAB.</div><div class="request-layout"><form id="request-form" class="portal-panel"><h2>Um novo pedido.</h2><p class="muted">Experimente organizar uma questão para os serviços académicos.</p><label>Tipo de pedido <select name="type" required><option value="">Seleccione</option><option>Informação académica</option><option>Declaração de matrícula</option><option>Consulta de equivalências</option><option>Apoio ao estudante</option><option>Outro pedido</option></select></label><label>Descrição <textarea name="description" required minlength="10" maxlength="1500" rows="5" placeholder="Use informação fictícia nesta demonstração."></textarea></label><button class="button">Guardar pedido demonstrativo <span>↗</span></button></form><section class="portal-panel"><div class="panel-title"><h2>Os meus pedidos locais</h2><span>◷</span></div><div id="request-list"></div></section></div>`);
portalWrite('perfil','O meu perfil',`<div class="profile-card portal-panel"><span class="profile-big">JE</span><div><h2>Joana Exemplo</h2><p>Engenharia Informática · 1.º ano</p><span class="status blue">Perfil fictício de demonstração</span></div></div><div class="dashboard-columns"><section class="portal-panel"><div class="panel-title"><h2>Preferências neste navegador</h2></div><form id="preferences-form"><label>Como prefere ser tratado na demonstração?<input name="displayName" maxlength="60" placeholder="Joana" autocomplete="off"></label><label class="check-option"><input type="checkbox" name="reducedMotion"> Reduzir animações neste navegador</label><button class="button small">Guardar preferências <span>✓</span></button></form></section><section class="portal-panel"><div class="panel-title"><h2>Os seus dados locais</h2></div><p class="muted">Favoritos, comparações, rascunhos, candidaturas demonstrativas e pedidos ficam apenas neste dispositivo. Não são sincronizados com uma conta.</p><button class="outline-button" id="export-local">Exportar dados locais ↓</button><button class="danger-button" id="clear-local">Apagar dados da demonstração</button><a class="text-link" href="/privacidade/">Como são tratados os dados <span>↗</span></a></section></div>`);
write('/privacidade/','Privacidade',`${crumb('Privacidade')}${pageHead('CLAREZA SOBRE OS SEUS DADOS','A sua informação.<br><em>Com transparência.</em>','Saiba como funciona o tratamento de dados nesta versão demonstrativa.')}<article class="prose wrap section"><h2>Dados desta demonstração</h2><p>O catálogo e o perfil académico são fictícios. Favoritos, lista de preparação, comparação, preferências, rascunhos, candidaturas e pedidos são guardados no armazenamento local deste navegador. Não existe sincronização entre dispositivos nem envio institucional desses registos.</p><h2>Informações nos formulários</h2><p>Utilize dados fictícios. A candidatura guarda localmente as informações introduzidas apenas quando guarda um rascunho ou conclui a demonstração. Não são solicitados documentos de identidade, dados bancários ou senhas institucionais.</p><h2>Controlar e apagar os dados</h2><p>Pode exportar ou apagar os dados em <a href="/portal/perfil/">O meu perfil</a>. Apagar o armazenamento do navegador também remove estes registos. Não é possível recuperá-los após a eliminação, salvo se tiver uma exportação própria.</p><h2>Acesso e recursos externos</h2><p>O login com ChatGPT é tratado pela hospedagem Sites. O site carrega fontes do Google Fonts e inclui links para recursos externos; cada fornecedor tem as suas próprias políticas. Fotografias ilustrativas estão guardadas nos ficheiros do site. Não foram adicionados rastreadores publicitários ou analítica.</p><h2>Antes de uma operação oficial</h2><p>A instituição deverá validar a política de privacidade, os prazos de conservação, as bases de tratamento, os canais de contacto e os fornecedores antes de recolher dados para candidaturas ou serviços reais.</p></article>`);
write('/acessibilidade/','Acessibilidade',`${crumb('Acessibilidade')}${pageHead('UMA EXPERIÊNCIA PARA MAIS PESSOAS','Acesso claro.<br><em>Participação com autonomia.</em>','Recursos para navegar e explorar esta experiência.')}<article class="prose wrap section"><h2>Navegação por teclado</h2><p>Utilize Tab para percorrer links e controlos, Enter ou Espaço para activar botões e Escape para fechar janelas e menus. O primeiro link de cada página permite saltar para o conteúdo principal.</p><h2>Leitura e orientação</h2><p>As páginas usam títulos hierárquicos, rótulos nos formulários, textos alternativos em imagens informativas e mensagens de estado para os fluxos interactivos.</p><h2>Movimento e ecrãs</h2><p>A interface adapta-se a ecrãs pequenos e respeita a preferência do sistema por movimento reduzido. Pode também reduzir as animações nas <a href="/portal/perfil/">preferências do portal</a>.</p><h2>Limites e melhorias</h2><p>Esta prévia ainda não passou por uma auditoria formal de conformidade. Se encontrar uma barreira, pode <a href="/contactos/?assunto=Apoio%20ao%20estudante">preparar uma mensagem</a> para documentar o problema.</p></article>`);
write('/sobre-o-projecto/','Sobre o projecto',`${crumb('Sobre o projecto')}${pageHead('UMA PRÉVIA PARA EXPLORAR','ISPAB.<br><em>Uma experiência em construção.</em>','Um website demonstrativo para o ISPAB, em Angola, com conteúdo e jornadas para validação.')}<article class="prose wrap section"><h2>O que está disponível</h2><p>Catálogo com pesquisa e filtros, páginas de curso, favoritos, comparação, candidatura em três etapas, área do candidato e portal com disciplinas, notas, horários, documentos e pedidos demonstrativos.</p><h2>O que precisa de integração</h2><p>Os dados académicos não são oficiais. Não existe submissão institucional de candidaturas, análise de documentos, cobrança, matrícula ou sistema de notas conectado. A entrada institucional está preparada para encaminhar ao login existente do SIGA Plus, sem recolher palavras-passe neste website. O administrador pode gerir os conteúdos públicos pelo SIGA, após activar a ligação pela API.</p><h2>Identidade e informação institucional</h2><p>O nome ISPAB e o país Angola foram fornecidos para esta proposta. A designação completa, os contactos, a história, o campus e a oferta oficial precisam de validação. Não são declarados credenciamentos, rankings ou parcerias. As imagens são ilustrativas.</p><h2>Referências de experiência</h2><p>Pesquisa realizada em 20 de Outubro de 2026. As referências orientam a estrutura; não existe afiliação a estas instituições nem reprodução do seu conteúdo.</p><ul><li><a href="https://unasp.br/cursos/" target="_blank" rel="noopener">UNASP</a>: organização dos cursos, ingresso e serviços ao aluno.</li><li><a href="https://www.ox.ac.uk/admissions" target="_blank" rel="noopener">University of Oxford</a>: descoberta de cursos e orientação de candidaturas.</li><li><a href="https://www.harvard.edu/" target="_blank" rel="noopener">Harvard University</a>: ligação entre ensino, pesquisa, vida no campus e serviços.</li><li><a href="https://www.zoom.com/" target="_blank" rel="noopener">Zoom</a>: hierarquia de navegação e apresentação de serviços. Não há salas ou videochamadas.</li></ul><h2>Dados da demonstração</h2><p>Os registos criados pelo visitante ficam apenas no navegador. Consulte a <a href="/privacidade/">informação de privacidade</a> e use dados fictícios ao experimentar os formulários.</p></article>`);
